<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder;use Spatie\Permission\Models\Permission;use Spatie\Permission\Models\Role;use Spatie\Permission\PermissionRegistrar;
class RolePermissionSeeder extends Seeder{public function run():void{app(PermissionRegistrar::class)->forgetCachedPermissions();$permissions=['documents.view','documents.register','documents.metadata.update','documents.upload','documents.replace','documents.preview','documents.download','documents.print','documents.verify','documents.approve','documents.reject','documents.archive','documents.restore','barcodes.view','barcodes.generate','barcodes.print','barcodes.reprint','users.view','users.create','users.update','users.disable','roles.view','roles.manage','geography.view','geography.manage','masters.view','masters.manage','metadata.view','metadata.manage','metadata.publish','audit.view','security.view','reports.view','reports.export','reports.export_sensitive','reports.bulk_export','bulk.upload','bulk.import','bulk.retry','bulk.manage','system.configure'];foreach($permissions as $p)Permission::firstOrCreate(['name'=>$p,'guard_name'=>'web']);$roles=['Super Administrator','System Administrator','Database Administrator','District Administrator','Circle Administrator','Document Registration Operator','Document Upload Operator','Document Verification Officer','Document Viewer','Auditor'];foreach($roles as $r)Role::firstOrCreate(['name'=>$r,'guard_name'=>'web']);Role::findByName('Super Administrator')->syncPermissions($permissions);Role::findByName('Document Registration Operator')->syncPermissions(['documents.view','documents.register','barcodes.view','barcodes.generate','barcodes.print','geography.view','masters.view','metadata.view']);Role::findByName('Document Upload Operator')->syncPermissions(['documents.view','documents.upload','documents.preview','barcodes.view','geography.view','masters.view']);Role::findByName('Document Verification Officer')->syncPermissions(['documents.view','documents.preview','documents.verify','documents.approve','documents.reject','geography.view','masters.view','metadata.view']);Role::findByName('Document Viewer')->syncPermissions(['documents.view','documents.preview','geography.view','masters.view']);Role::findByName('Auditor')->syncPermissions(['audit.view','security.view','documents.view','reports.view']);}}
